<script setup>
import {ref, computed, onMounted, watch} from 'vue';
import {useRoute, onBeforeRouteLeave} from 'vue-router';
import {usePortalShell} from '../stores/portal.js';
import {readDocument} from '../portal/services/documents.js';
const route=useRoute(), shell=usePortalShell();
const record=ref(null), blocks=ref([]), fields=ref([]), releases=ref([]), warnings=ref([]);
const extracting=ref(false), extractionReport=ref(null);
const fieldSearch=ref(''), fieldFilter=ref('all'), showLocations=ref(false);
const visibleFields=computed(()=>fields.value.map((item,index)=>({...item,number:index+1})).filter(f=>(fieldFilter.value!=='pending'||!f.confirmed)&&f.name.toLowerCase().includes(fieldSearch.value.trim().toLowerCase())));
const ready=computed(()=>fields.value.length>0&&confirmed.value===fields.value.length);
const selected=ref(''), busy=ref(false), error=ref(''), dirty=ref(false), mode=ref('structure');
const picker=ref(false), adjusting=ref(false), selection=ref(null), paper=ref(null), trialFile=ref(null), result=ref(null), confirmModal=ref('');
const field=computed(()=>fields.value.find(f=>f.id===selected.value));
const confirmed=computed(()=>fields.value.filter(f=>f.confirmed).length);
const base=()=>'/api/contract-templates/'+route.params.id;
const points=s=>Array.from(s);
async function load(){try{const data=await shell.api(base()+'/review');record.value=data.template;blocks.value=data.blocks;fields.value=data.fields;releases.value=data.releases;warnings.value=data.warnings;selected.value=fields.value[0]?.id||'';dirty.value=false;}catch(e){error.value=e.message;}}
onMounted(load);
watch(()=>route.params.id,load);
function change(){if(field.value)field.value.confirmed=false;dirty.value=true;}
function select(id){selected.value=id;requestAnimationFrame(()=>document.getElementById('region-'+id)?.scrollIntoView({block:'nearest',behavior:'smooth'}));}
function pieces(block){const text=points(block.text),rows=fields.value.filter(f=>f.block_id===block.id).sort((a,b)=>a.start-b.start);let cursor=0,out=[];for(const f of rows){if(f.start>cursor)out.push({text:text.slice(cursor,f.start).join(''),start:cursor});out.push({text:text.slice(f.start,f.end).join(''),start:f.start,field:f});cursor=f.end;}if(cursor<text.length)out.push({text:text.slice(cursor).join(''),start:cursor});return out;}
function capture(){selection.value=null;const s=window.getSelection();if(!s?.rangeCount||s.isCollapsed)return;const r=s.getRangeAt(0);const element=r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement;const block=element.closest('[data-block]');if(!block||!paper.value?.contains(block)||!block.contains(r.endContainer))return;const before=r.cloneRange();before.selectNodeContents(block);before.setEnd(r.startContainer,r.startOffset);const start=points(before.toString()).length,end=start+points(r.toString()).length;if(start===end)return;selection.value={block_id:block.dataset.block,start,end,text:r.toString()};}
function addRegion(location){const block=blocks.value.find(b=>b.id===location.block_id);if(!block)return;const target=adjusting.value?selected.value:null;if(fields.value.some(f=>f.id!==target&&f.block_id===location.block_id&&location.start<f.end&&location.end>f.start)){error.value='选区与已有字段重叠，请调整范围';return;}if(adjusting.value&&field.value){Object.assign(field.value,{block_id:location.block_id,start:location.start,end:location.end,confirmed:false});}else{const id=crypto.randomUUID();fields.value.push({id,name:'新增填写区域',block_id:location.block_id,start:location.start,end:location.end,type:'text',policy:'manual',required:true,max_length:200,minimum:null,maximum:null,options:[],origin:'manual',confirmed:false});selected.value=id;}dirty.value=true;picker.value=false;adjusting.value=false;selection.value=null;error.value='';window.getSelection()?.removeAllRanges();}
function beginAdd(adjust=false){mode.value='structure';adjusting.value=adjust;picker.value=true;}
const pickBlock=ref(''),pickStart=ref(0),pickEnd=ref(1);
const chosenBlock=computed(()=>blocks.value.find(b=>b.id===pickBlock.value));
watch(pickBlock,()=>{pickStart.value=0;pickEnd.value=chosenBlock.value?.kind==='cell'?points(chosenBlock.value.text).length:Math.min(1,points(chosenBlock.value?.text||'').length);});
async function save(){busy.value=true;error.value='';try{record.value=await shell.api(base()+'/review','PUT',{revision:record.value.revision,source_id:record.value.source_id,fields:fields.value});dirty.value=false;return true;}catch(e){error.value=e.message;return false;}finally{busy.value=false;}}
function confirmField(){if(!field.value)return;field.value.confirmed=true;dirty.value=true;const next=fields.value.find(f=>!f.confirmed);if(next)select(next.id);}
function remove(){fields.value=fields.value.filter(f=>f.id!==selected.value);selected.value=fields.value[0]?.id||'';dirty.value=true;confirmModal.value='';}
async function extract(){confirmModal.value='';busy.value=true;extracting.value=true;error.value='';extractionReport.value=null;try{const response=await shell.api(base()+'/extract-fields','POST',{revision:record.value.revision,model_config_data:shell.model});extractionReport.value={count:response.fields.length,skipped:response.skipped||[]};if(response.fields.length){fields.value=response.fields;selected.value=fields.value[0]?.id||'';dirty.value=true;shell.notify(`已提取 ${fields.value.length} 个填写区域，请逐项核验`);}}catch(e){error.value=e.message;}finally{busy.value=false;extracting.value=false;}}

async function publish(){confirmModal.value='';if(dirty.value&&!await save())return;busy.value=true;try{await shell.api(base()+'/publish','POST',{revision:record.value.revision});await load();shell.notify('已发布模板规则版本');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function trial(event){const file=event.target.files[0];event.target.value='';if(!file)return;if(dirty.value&&!await save())return;busy.value=true;error.value='';try{const upload=await readDocument(file);result.value=await shell.api(base()+'/trial','POST',{source_id:upload.source_id,revision:record.value.revision});}catch(e){error.value=e.message;}finally{busy.value=false;}}
const quote=computed(()=>field.value?points(blocks.value.find(b=>b.id===field.value.block_id)?.text||'').slice(field.value.start,field.value.end).join(''):'');
onBeforeRouteLeave(()=>{if(busy.value)return false;return !dirty.value||window.confirm('存在未保存规则，确定离开？');});
</script>
<template>
 <div class="template-review">
  <div class="tr-crumb"><RouterLink to="/templates">合同模板</RouterLink> / 模板核验</div>
  <div v-if="error" class="tr-error" role="alert">{{error}} <button @click="error=''">关闭</button></div>
  <template v-if="record">
   <div class="tr-heading"><div class="tr-heading-copy"><div class="tr-eyebrow">模板工作台 <span>/ 人工核验</span></div><h1>{{record.name}} <span>{{dirty?'有未保存更改':record.review_status==='published'?'已发布':'待人工核验'}}</span></h1><p>{{record.filename}} · {{releases.length?`已发布 ${releases.length} 个版本`:'尚未发布'}} · {{fields.length}} 个填写区域</p></div><div class="tr-actions"><button class="button" :disabled="busy" @click="confirmModal='extract'">{{extracting?'正在提取…':'✧ AI 提取'}}</button><button class="button" :disabled="busy" @click="save">保存草稿</button><button class="button" :disabled="busy||!fields.length||confirmed!==fields.length" @click="trialFile.click()">试算验证</button><button class="button primary" :disabled="busy||!fields.length||confirmed!==fields.length" @click="confirmModal='publish'">发布版本</button></div></div>
   <div class="tr-steps" aria-label="模板处理步骤"><span class="is-complete"><b>✓</b> 接收模板</span><i></i><span :class="{'is-complete':fields.length}"><b>{{fields.length?'✓':'02'}}</b> 提取填写区域</span><i></i><strong :class="{'is-complete':ready}"><b>{{ready?'✓':'03'}}</b> 人工核验</strong><i></i><span><b>04</b> 发布使用</span></div>
   <details v-if="warnings.length" class="tr-warning"><summary><span class="tr-warning-icon" aria-hidden="true">!</span><strong>部分内容需人工关注</strong><span class="tr-warning-summary">复杂内容不参与完整验证</span><span class="tr-warning-toggle">查看说明</span></summary><p>{{warnings.join('；')}}。可维护规则，试算将保留“无法确定”。</p></details>
   <div v-if="extracting" class="tr-extraction-status" role="status" aria-live="polite"><span class="tr-spinner" aria-hidden="true"></span><div><strong>正在识别合同填写区域</strong><p>AI 正在分析原文并校验字段位置，请稍候。</p></div></div>
   <div v-else-if="extractionReport" class="tr-extraction-status" role="status" aria-live="polite"><div><strong>{{extractionReport.count ? `已识别 ${extractionReport.count} 个填写区域，请逐项核验` : '本次未识别到可定位的填写区域，已有标记已保留'}}</strong><p v-if="!extractionReport.count">可以在原文中选中文字，或通过“手动添加”标记位置。</p><details v-if="extractionReport.skipped.length"><summary>{{extractionReport.skipped.length}} 个候选未通过定位校验，查看原因</summary><p v-for="(item,i) in extractionReport.skipped" :key="i">{{item.name}}：{{item.reason}}</p></details></div></div>
   <div class="tr-workspace" :class="{'is-busy':busy}">
    <aside class="tr-panel"><div class="tr-title"><span>填写区域 <small class="tr-count">{{fields.length}}</small></span><button :disabled="busy" @click="beginAdd()">＋ 手动添加</button></div><div class="tr-progress"><div class="tr-progress-caption"><span>核验进度</span><strong>{{confirmed}} <span>/ {{fields.length}}</span></strong></div><div><i :style="{width:(fields.length?confirmed/fields.length*100:0)+'%'}"></i></div></div><div v-if="fields.length" class="tr-field-tools"><input v-model="fieldSearch" type="search" placeholder="搜索填写区域" aria-label="搜索填写区域"><div><button :class="{active:fieldFilter==='all'}" @click="fieldFilter='all'">全部 {{fields.length}}</button><button :class="{active:fieldFilter==='pending'}" @click="fieldFilter='pending'">待核验 {{fields.length-confirmed}}</button></div></div><div class="tr-field-list"><button v-for="f in visibleFields" :key="f.id" class="tr-field" :class="{selected:selected===f.id,'is-confirmed':f.confirmed}" :aria-pressed="selected===f.id" :disabled="busy" @click="select(f.id)"><b>{{String(f.number).padStart(2,'0')}}</b><span>{{f.name}}<small>{{f.origin==='ai'?'AI 提取':'手动添加'}} · {{f.policy==='manual'?'转人工':'按规则校验'}}</small></span><em :title="f.confirmed?'已确认':'待核验'">{{f.confirmed?'✓':'○'}}</em></button><div v-if="fields.length&&!visibleFields.length" class="tr-empty tr-no-matches">{{fieldFilter==='pending'&&!fieldSearch?'全部区域已核验完成':'没有匹配的填写区域'}}</div></div><div v-if="!fields.length" class="tr-empty tr-empty-fields"><span class="tr-empty-icon" aria-hidden="true">＋</span><h3>添加第一个填写区域</h3><p>让 AI 识别合同中的可填内容，<br>也可以选中正文手动标记。</p><button class="button tr-extract-button" :disabled="busy" @click="confirmModal='extract'">✧ AI 智能提取</button></div></aside>
    <section class="tr-panel tr-document-panel"><div class="tr-title"><span>合同内容 <small class="tr-document-caption">原文标记与定位</small></span><div class="tr-tabs"><button :class="{active:mode==='structure'}" @click="mode='structure'">标记视图</button><button :class="{active:mode==='original'}" @click="mode='original'">原排版</button></div></div><div class="tr-guide"><span>{{adjusting?'请选取新的原文范围，点击“更新到此位置”。':'选中单段文字或空白，即可添加填写区域；表格单元格可通过手动添加定位。'}}</span><label v-if="mode==='structure'" class="tr-location-toggle"><input type="checkbox" v-model="showLocations">显示段落位置</label></div><iframe v-if="mode==='original'" class="tr-iframe" :src="'/static/document-preview.html?readonly=1&source='+record.source_id" title="模板原排版"></iframe><div v-else class="tr-paper-wrap"><div class="tr-document-legend"><span><i></i>待核验区域</span><span><i class="is-confirmed"></i>已确认区域</span></div><article ref="paper" class="tr-paper" @mouseup="capture"><template v-for="block in blocks" :key="block.id"><small v-if="showLocations" class="tr-block-label">{{block.section}} · {{block.kind==='cell'?'表格单元格':'段落'}} · {{block.id}}</small><p :data-block="block.id" :class="{'tr-cell':block.kind==='cell','tr-document-heading':block===blocks[0]&&block.text.length<50&&!/[：:；;。]/.test(block.text)&&!fields.some(f=>f.block_id===block.id)}"><template v-for="(part,i) in pieces(block)" :key="i"><span v-if="part.field" :id="'region-'+part.field.id" class="tr-mark" :class="{selected:selected===part.field.id,confirmed:part.field.confirmed,manual:part.field.policy==='manual'}" @click="selected=part.field.id" :title="part.field.name">{{part.text}}</span><span v-else>{{part.text}}</span></template></p></template></article></div><div v-if="selection" class="tr-selection"><span>已选 {{selection.end-selection.start}} 字符</span><button class="button primary" :disabled="busy" @mousedown.prevent @click="addRegion(selection)">{{adjusting?'更新到此位置':'＋ 添加填写区域'}}</button><button @click="selection=null;adjusting=false">取消</button></div></section>
    <aside class="tr-panel"><div class="tr-title">字段核验 <small v-if="field">{{field?.origin==='ai'?'AI 候选':'人工标记'}}</small></div><div v-if="field" class="tr-rule"><div class="tr-rule-heading"><span>当前区域 · {{String(fields.findIndex(f=>f.id===selected)+1).padStart(2,'0')}}</span><b :class="{confirmed:field.confirmed}">{{field.confirmed?'已确认':'待核验'}}</b></div><h2>{{field.name}}</h2><div class="tr-quote-label">原文片段</div><div class="tr-quote">{{quote}}</div><div class="tr-range"><button @click="beginAdd(true)">调整范围</button><button @click="confirmModal='delete'">删除标记</button></div><label>字段名称<input aria-label="字段名称" v-model="field.name" maxlength="100" @input="change"></label><label>填写类型<select v-model="field.type" @change="change"><option value="text">文本</option><option value="integer">整数</option><option value="date">日期 YYYY-MM-DD</option><option value="enum">枚举选项</option></select></label><label>免审处理<select aria-label="免审处理" v-model="field.policy" @change="change"><option value="manual">填写后转人工审批</option><option value="conditional">符合规则时允许免审</option></select></label><label>最大字符数<input v-model.number="field.max_length" type="number" min="1" max="2000" @input="change"></label><div v-if="field.type==='integer'" class="tr-number"><label>下限<input v-model.number="field.minimum" type="number" @input="change"></label><label>上限<input v-model.number="field.maximum" type="number" @input="change"></label></div><label v-if="field.type==='enum'">允许值（每行一项）<textarea :value="field.options.join('\n')" @input="field.options=$event.target.value.split('\n');change()"></textarea></label><label class="tr-checkbox">必须填写<input v-model="field.required" type="checkbox" @change="change"></label><div class="tr-note">原文位置 {{field.block_id}} · 字符 {{field.start+1}}–{{field.end}}。请确认区域边界和规则，固定条款不应标记为可填写。</div><div class="tr-rule-footer"><button class="button primary tr-full" :disabled="busy||!field.name.trim()" @click="confirmField">{{field.confirmed?'已确认 · 下一项':'确认并下一项'}}</button><p>{{ready?'全部区域已确认，可保存并试算验证':'确认位置与规则后，继续核验下一区域'}}</p></div></div><div v-else class="tr-empty tr-empty-rule"><span class="tr-empty-icon" aria-hidden="true">✓</span><h3>准备核验填写规则</h3><p>选择左侧填写区域，<br>在这里设置类型、范围与免审规则。</p><div class="tr-empty-tip">每个区域确认完成后，<br>即可试算验证并发布模板。</div></div></aside>
   </div><div class="tr-foot">固定内容按文字与结构校验 · 修改规则后请重新确认并保存 <span>{{busy?'正在处理，请稍候…':dirty?'尚未保存':'已保存'}}</span></div>
  </template><div v-else-if="!error" class="tr-empty">正在加载模板…</div>
  <input ref="trialFile" type="file" accept=".docx" hidden @change="trial">
  <Teleport to="body"><div v-if="picker" class="tr-overlay" @click.self="picker=false"><section class="tr-dialog" role="dialog" aria-modal="true" aria-label="手动标记位置"><h2>{{adjusting?'调整填写范围':'手动添加填写区域'}}</h2><p>可直接选中原文，或指定段落 / 表格单元格内的字符范围。字符位置从 1 开始。</p><label>原文位置<select aria-label="原文位置" v-model="pickBlock"><option value="">请选择位置</option><option v-for="b in blocks" :key="b.id" :value="b.id">{{b.id}} · {{b.kind==='cell'?'表格':'段落'}} · {{b.text.slice(0,60)}}</option></select></label><template v-if="chosenBlock"><div class="tr-quote">{{chosenBlock.text}}</div><div class="tr-number"><label>开始位置<input aria-label="开始位置" :value="pickStart+1" type="number" min="1" :max="points(chosenBlock.text).length" @input="pickStart=Number($event.target.value)-1"></label><label>结束位置（包含）<input aria-label="结束位置（包含）" v-model.number="pickEnd" type="number" min="1" :max="points(chosenBlock.text).length"></label></div><div class="tr-quote">选中：{{points(chosenBlock.text).slice(pickStart,pickEnd).join('')}}</div></template><footer><button class="button" @click="picker=false">返回正文选择</button><button class="button primary" :disabled="!chosenBlock||pickStart<0||pickEnd<=pickStart||pickEnd>points(chosenBlock.text).length" @click="addRegion({block_id:pickBlock,start:pickStart,end:pickEnd})">保存位置</button></footer></section></div>
   <div v-if="confirmModal" class="tr-overlay"><section class="tr-dialog" role="dialog" aria-modal="true"><h2>{{{extract:'AI 提取候选字段',publish:'发布模板版本',delete:'删除填写标记'}[confirmModal]}}</h2><p>{{{extract:'AI 结果将替换当前候选字段，包括未保存的手动标记。提取失败时保留已有内容；成功后仍需人工核验。',publish:'将保存当前规则并创建不可变的发布版本。后续修改草稿不会覆盖历史版本。',delete:'删除后原文保持不变，该位置将作为固定内容检查。'}[confirmModal]}}</p><footer><button class="button" @click="confirmModal=''">取消</button><button class="button primary" @click="confirmModal==='extract'?extract():confirmModal==='publish'?publish():remove()">确认</button></footer></section></div>
   <div v-if="result" class="tr-overlay"><section class="tr-dialog tr-report" role="dialog" aria-label="试算报告"><h2>试算结果：{{{PASS:'规则通过',DIFFERENT:'存在差异',UNDETERMINED:'无法确定'}[result.result]}}</h2><p>{{result.reason}}</p><div class="tr-note">{{result.coverage}}。此结果不触发自动免审。</div><h3>填写值</h3><div v-for="v in result.values" :key="v.id" class="tr-report-row"><strong>{{v.name}}</strong><span>{{v.value}}</span><small>{{v.reason||'符合配置'}}</small></div><h3 v-if="result.differences.length">固定内容差异</h3><div v-for="(d,i) in result.differences" :key="i" class="tr-report-row"><strong>{{d.reason}}</strong><del>{{d.original}}</del><span>{{d.current}}</span></div><footer><button class="button" @click="result=null">关闭</button></footer></section></div>
  </Teleport>
 </div>
</template>
